    [15] = {
      beijing = 1021,
      dialog = 3,
      music = "09_Suspect",
      renwu = "npc",
      ruchang = 0,
      sentence = "I flipped open Dad's notebook which he always carried with him. 10 years of his notes. Maybe what I'm looking for is inside.",
