      beijing = 1021,
      dialog = 3,
      music = "09_Suspect",
      renwu = "npc",
      ruchang = 0,
      sentence = "In the notes from 17 years ago, amidst a bunch of notes on superpowers, there was one case that didn't come up in any newspaper or online search.",
