    [19] = {
      beijing = 1021,
      dialog = 3,
      music = "09_Suspect",
      renwu = "npc",
      ruchang = 0,
      sentence = "A family of four suddenly disappeared at a waterfall in the northern district, without a trace of struggle at the scene. The only thing left was a sedan locked from the inside and a busted camera.",
