    },
    [20] = {
      beijing = 1021,
      dialog = 3,
      music = "09_Suspect",
      renwu = "npc",
      ruchang = 0,
      sentence = "The police formed a special unit, but none of their efforts ever turned up the husband, wife, or their boy and girl. As time passed, it just became another unsolved case.",
