    [21] = {
      beijing = 1021,
      dialog = 3,
      music = "09_Suspect",
      renwu = "npc",
      ruchang = 0,
      sentence = "Due to inaccessibility of information at the time and deliberate concealment by the police, there was no news anywhere of this incident recorded in the notebook.",
