    [45] = {
      beijing = 74390,
      bganim = 0,
      dialog = 3,
      music = "404_Hazy_Starry_Night",
      renwu = "npc",
      sentence = "Gavin propped himself against my side, his eyes lowered, his hair brushing against my neck.",
