    },
    [46] = {
      beijing = 74390,
      dialog = 2,
      idx = 4,
      male = 4,
      music = "404_Hazy_Starry_Night",
      renming = "Gavin",
      renwu = "npc",
      sentence = "He said that you performed the tasks with them meticulously during the night patrol, pressing on despite your fear.",
