      beijing = 74390,
      dialog = 2,
      idx = 4,
      male = 4,
      music = "404_Hazy_Starry_Night",
      renming = "Gavin",
      renwu = "npc",
      sentence = "And although you knew he was looking for the medal, you didn't think him utilitarian.",
