    },
    [48] = {
      beijing = 74390,
      dialog = 2,
      idx = 4,
      male = 4,
      music = "404_Hazy_Starry_Night",
      renming = "Gavin",
      renwu = "npc",
      sentence = "He believes you're a scrupulous person, and your show will be quite rewarding, so he wants to participate.",
      voice = 2,
      next = {49}
    },
    [49] = {
      beijing = 74390,
      dhead = 111,
      dialog = 1,
      music = "404_Hazy_Starry_Night",
      renming = "$u",
      renwu = "npc",
      sentence = "Why would I see him as utilitarian? Isn't it normal to want to recover something you hold dear?",
