    },
    [50] = {
      beijing = 74390,
      dialog = 3,
      music = "404_Hazy_Starry_Night",
      renwu = "npc",
      sentence = "Running my cold finger across his dashing brows, I also gave voice to my true thoughts.",
      next = {51}
    },
    [51] = {
      beijing = 74390,
      dhead = 107,
      dialog = 1,
      music = "404_Hazy_Starry_Night",
      renming = "$u",
      renwu = "npc",
      sentence = "I know you guys prefer not to talk too much about your achievements or glories.",
      next = {52}
    },
    [52] = {
      beijing = 74390,
      dialog = 3,
      music = "404_Hazy_Starry_Night",
      renwu = "npc",
      sentence = "There were a whole lot of medals in our house. Gavin tended to look indifferent when accepting them, but he always made sure they were kept safe.",
      next = {53}
    },
    [53] = {
      beijing = 74390,
      dialog = 3,
      music = "404_Hazy_Starry_Night",
      renwu = "npc",
      sentence = "I knew very well that deep down there, he saw these things as tokens of acknowledgment of collective efforts, and they were steeped in his firm bonding with many people and things.",
      next = {54}
    },
    [54] = {
      beijing = 74390,
      dialog = 3,
      music = "404_Hazy_Starry_Night",
      renwu = "npc",
      sentence = "Neither Cheney nor Gavin had taken this path for glory and medals.",
      next = {55}
    },
    [55] = {
      beijing = 74390,
      dialog = 3,
      music = "404_Hazy_Starry_Night",
      renwu = "npc",
      sentence = "But these things had paved the way for them, granting them a firmer footing on the path.",
      next = {56}
    },
    [56] = {
      beijing = 74390,
      dhead = 105,
      dialog = 1,
      music = "404_Hazy_Starry_Night",
      renming = "$u",
      renwu = "npc",
      sentence = "But these well-deserved honors, and the hardships behind the story… For my selfish personal reasons…",
      next = {57}
    },
    [57] = {
      beijing = 74390,
      dhead = 105,
      dialog = 1,
      music = "404_Hazy_Starry_Night",
      renming = "$u",
      renwu = "npc",
      sentence = "I would very much like more people to see them, so that they'll be known.",
      next = {58}
    },
    [58] = {
      beijing = 74390,
      dhead = 106,
      dialog = 1,
      music = "404_Hazy_Starry_Night",
      renming = "$u",
      renwu = "npc",
      sentence = "I think you should take the lead and go public with more of it, Officer Gavin. I'll do an exclusive interview with you.",
      next = {59}
    },
    [59] = {
      beijing = 74390,
      dialog = 3,
      music = "404_Hazy_Starry_Night",
      renwu = "npc",
      sentence = "I turned my head a little in an effort to hide my mood swings from Gavin. For a while, he seemed to be thinking, and then a warm voice came from beside me.",
      next = {60}
    },
    [60] = {
      beijing = 74390,
      dialog = 2,
      idx = 4,
      male = 4,
      music = "404_Hazy_Starry_Night",
      renming = "Gavin",
      renwu = "npc",
